r"""
Crescopus - Samsung icon fix: favicon.ico, 512px icons and app manifest

HOW TO USE
  1. Save this file in your Crescopus project folder (next to wsgi.py).
  2. In PowerShell, in that folder, with your venv active:
         python apply_icon_fix.py
  3. It lists every file as new / updated / same. Any file it replaces is
     copied first to _backup_apply_icon_fix\ so you can undo by copying back.

Your .env is never read or changed.
"""
import base64, os, shutil, sys

FILES = [
    ("app/__init__.py", ""),
    ("app/templates/base.html", ""),
    ("app/static/favicon.ico", ""),
    ("app/static/favicon-512.png", ""),
    ("app/static/icon-maskable-512.png", ""),
    ("app/static/manifest.webmanifest", ""),
]
BACKUP = "_backup_apply_icon_fix"
NEXT = "restart python wsgi.py, then commit and push so Render redeploys. On the phone: Samsung Internet > menu > Settings > Personal browsing data > Delete browsing data, tick Browsing history AND Cached images and files, then Delete."

def main():
    root = os.path.dirname(os.path.abspath(__file__))
    if not os.path.isfile(os.path.join(root, "app", "__init__.py")) or not os.path.isfile(os.path.join(root, "wsgi.py")):
        sys.exit("Stopped: put this file in the Crescopus project folder (next to wsgi.py and the app folder), then run it again.")
    backup = os.path.join(root, BACKUP)
    changed = 0
    for rel, b64 in FILES:
        path = os.path.join(root, *rel.split("/"))
        data = base64.b64decode(b64)
        status = "new     "
        if os.path.exists(path):
            with open(path, "rb") as fh:
                if fh.read() == data:
                    print("same     " + rel)
                    continue
            dest = os.path.join(backup, *rel.split("/"))
            os.makedirs(os.path.dirname(dest), exist_ok=True)
            shutil.copy2(path, dest)
            status = "updated "
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "wb") as fh:
            fh.write(data)
        changed += 1
        print(status + " " + rel)
    print("\nDone - %d of %d files written." % (changed, len(FILES)))
    if os.path.isdir(backup):
        print("Originals of replaced files are in " + BACKUP + os.sep)
    if NEXT:
        print("Next: " + NEXT)

if __name__ == "__main__":
    main()
